import json
def C(title,scn,prompt,cues,target,en,cando):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scn,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":cando}
d={
"b2-colombiaandina-01":C("Laws for the Páramos","You are Meg. You and Carlos are watching a documentary about the páramos of Colombia, and he asks what the environmental groups want.","Tell Carlos what the environmental groups ask for.",["Say that they ask for laws","Say what the laws should do"],"Piden leyes que protejan los páramos.","They are asking for laws that protect the páramos.","I can say what I am looking for or what does not exist with *que* + subjunctive (*Busco un guía que conozca…*)."),
"b2-colombiaandina-02":C("A City at 2,600 Metres","You are Carlos. You and Meg are planning a trip and reading about Bogotá, and she asks what surprises visitors.","Tell Meg what surprises many visitors, commenting on the fact.",["Mention the height of the city","Say that it surprises many visitors"],"El hecho de que la ciudad esté a 2600 metros sorprende a muchos visitantes.","The fact that the city is at 2,600 metres surprises many visitors.","I can comment on a known fact with *el hecho de que* + subjunctive."),
"b2-colombiaandina-03":C("The City of Eternal Spring","You are Meg. You and Carlos are reading an article about Medellín, and he asks whether it is a hot city.","Correct the idea that Medellín is hot and give the real reason.",["Reject the idea that it is hot","Say what its climate is like"],"No es que haga mucho calor, sino que la temperatura casi no cambia.","It is not that it is very hot, but that the temperature hardly changes.","I can reject a reason and give the real one with *no es que* + subjunctive and *sino que* + indicative."),
"b2-colombiaandina-04":C("Coffee Picked by Hand","You are Carlos. You and Meg are watching a documentary about the Coffee Cultural Landscape, and she asks how the coffee is harvested.","Tell Meg how the coffee is harvested.",["Say how it is picked","Say why it is done that way"],"El café se recoge a mano, porque el terreno es difícil.","The coffee is picked by hand, because the terrain is difficult.","I can describe how something is done with the passive *se* (*se recoge*, *se secan*)."),
"b2-colombiaandina-05":C("Where Gabo Began","You are Meg. You and Carlos are reading about García Márquez, and he asks whether he began as a novelist.","Correct Carlos with a stance adverb: say how he really began his career.",["Use an adverb that corrects an expectation","Say what his first work was"],"En realidad, empezó su carrera como periodista.","In fact, he began his career as a journalist.","I can comment on a fact with a stance adverb such as *en realidad*, *en rigor* or *afortunadamente*."),
"b2-colombiaandina-consolidation":C("Crops for the Páramo","You are Carlos. After the unit on the Colombian Andes, Meg asks what the farmers of the páramos need.","Tell Meg what the farmers of the páramo need.",["Say that they need crops","Say that the crops should not harm the water"],"Los campesinos necesitan cultivos que no dañen el agua del páramo.","The farmers need crops that do not harm the water of the páramo.","I can say what I am looking for or what does not exist with *que* + subjunctive.")}
open('/home/user/parlour-read-a/challenges-colombia-andes.json','w',encoding='utf8').write(json.dumps(d,indent=2,ensure_ascii=False))
